  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      var title = newTodoInput.value.trim();
      if (title === '') return;
      var todos = loadTodos();
      todos.push({ id: nextId(), title: title, completed: false });
      saveTodos(todos);
      newTodoInput.value = '';
      render();
    }
  });

  // ── Individual checkbox toggle ──
  // Handle all toggle clicks in one place.  A real browser toggles the
  // checkbox natively on click; happy-dom does not.  We detect which
  // environment we are in by comparing target.checked against the model
  // state: if the browser already toggled it we read the native result,
  // otherwise we toggle the model manually.  No preventDefault() is needed
  // because we never fight the browser's own toggle.
  todoList.addEventListener('click', function (e) {
    var target = e.target;
    var li = target.closest('li');
    if (!li) return;
    var id = parseInt(li.getAttribute('data-id'), 10);

    if (target.classList.contains('toggle')) {
      var todos = loadTodos();
      var todo = todos.find(function (t) { return t.id === id; });
      if (todo) {
        // Real browsers toggle target.checked on click natively; happy-dom
        // does not.  If the DOM already reflects the toggled state, use it;
        // otherwise toggle the model.
        var newCompleted = target.checked !== todo.completed ? target.checked : !todo.completed;
        todo.completed = newCompleted;
        saveTodos(todos);
        target.checked = todo.completed;
        li.classList.toggle('completed', todo.completed);
        updateTodoCount(todos);
        updateClearCompleted(todos);
        updateToggleAll(todos);
        // Remove li from DOM when it no longer matches the active filter
